mapper.select:
select n.*,u.user_name,b.company_logo,b.real_name,b.company_name,b.card_id, user_name, b.first_product, b.first_product_img, (select count(*) from industry_news_like l where l.news_id = n.news_id) as likeCount, (select count(*) from industry_news_comment t where t.news_id = n.news_id) as commentCount
,(select if(count(*)>0,1,0) from industry_news_like l where l.news_id = n.news_id and l.user_id = #{loginUserId}) as isLike
from industry_news n left join tb_user u on u.user_id = n.user_id LEFT JOIN `business_card` b ON b.`user_id` = n.`user_id` where n.news_id = #{newsId}

select n.*, u.user_name,b.company_logo,b.real_name,b.company_name,b.card_id from industry_news n left join tb_user u on u.user_id = n.user_id LEFT JOIN `business_card` b ON b.`user_id` = n.`user_id` AND b.`card_status` = 1
and u.user_id = #{industryNews.userId}
and n.status = #{industryNews.status}
and n.is_enable = #{industryNews.isEnable}
and n.industry_type like concat("%",#{industryNews.industryType},"%")
and n.release_type = #{industryNews.releaseType}
and n.sys_user_name like concat("%",#{industryNews.sysUserName},"%")
and u.user_name like concat("%",#{industryNews.userName},"%")
and n.enterprise_name like concat("%",#{industryNews.enterpriseName},"%")
and n.title like concat("%",#{industryNews.title},"%")
and n.title like concat("%",#{industryNews.keyWord},"%")
order by n.create_time desc
